import { component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import {
  liveReviewSnapshot,
  type LiveReviewSnapshot,
} from "../../utils/live-review";
import { WritingTools } from "./writing-tools";

export const LiveReviewPanel = component$<{ folioId: string }>(
  ({ folioId }) => {
    const state = useStore<{ snapshot: LiveReviewSnapshot }>({
      snapshot: liveReviewSnapshot(),
    });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(
      ({ cleanup }) => {
        state.snapshot = liveReviewSnapshot();
        const update = (event: Event) => {
          state.snapshot = (event as CustomEvent<LiveReviewSnapshot>).detail;
        };
        window.addEventListener("twyne:live-review", update);
        cleanup(() => window.removeEventListener("twyne:live-review", update));
      },
      { strategy: "document-ready" },
    );
    const snapshot = state.snapshot;
    const result = snapshot.folioId === folioId ? snapshot.result : null;
    return (
      <div class="live-review-panel">
        <p class="panel-meta" role="status">
          {snapshot.folioId === folioId
            ? snapshot.message
            : "Review follows your saved draft."}
        </p>
        <p class="live-review-panel__disclosure">
          Saved writing is sent for automatic analysis. Pause above the
          manuscript at any time. Findings are suggestions; your words stay
          yours.
        </p>
        {result && (
          <>
            {snapshot.status !== "current" && snapshot.status !== "reading" && (
              <p class="panel-meta">
                Previous reading. These findings may no longer match your draft.
              </p>
            )}
            {!!result.brief?.weakest.length && (
              <section class="live-review-panel__section">
                <h3 class="dept-label">Sharpen the dossier</h3>
                {result.brief.weakest.slice(0, 3).map((field) => (
                  <p key={field.field}>
                    <strong>
                      {field.field === "successSignal"
                        ? "Success signal"
                        : field.field}
                    </strong>
                    : {field.diagnosis}
                  </p>
                ))}
                <Link
                  class="panel-meta focus-ring"
                  href={`/dossier/refine/?folio=${encodeURIComponent(folioId)}`}
                >
                  Refine the dossier ↗
                </Link>
              </section>
            )}
            <section class="live-review-panel__section">
              <h3 class="dept-label">Passages to consider</h3>
              <p class="panel-meta">{result.coverage}</p>
              {result.passages
                .filter((item) => item.kind !== "nothing")
                .slice(0, 4)
                .map((item) => (
                  <details key={item.passage.id} class="live-review-passage">
                    <summary>
                      {
                        {
                          advice: "Consider a revision",
                          question: "Clarify for the reader",
                          evidence: "Check supporting evidence",
                          cut: "Check what this adds",
                          nothing: "No issue",
                        }[item.kind]
                      }
                      {(item.confidence ?? 0) < 0.5 ? " · tentative" : ""}
                    </summary>
                    <blockquote>{item.passage.text}</blockquote>
                  </details>
                ))}
              {result.passages.every((item) => item.kind === "nothing") && (
                <p>No clear issue in the passages checked.</p>
              )}
            </section>
            {!!result.notes?.some(
              (note) => note.verdict && !note.verdict.pass,
            ) && (
              <section class="live-review-panel__section">
                <h3 class="dept-label">Check the advice, too</h3>
                {result.notes
                  .filter((note) => note.verdict && !note.verdict.pass)
                  .map((note) => (
                    <p key={note.id}>
                      <strong>{note.author}</strong>:{" "}
                      {note.verdict!.reasons.join(" ")}
                    </p>
                  ))}
                <p class="panel-meta">
                  Tentative checks against your dossier and feedback
                  preferences. The original notes remain available in Cast.
                </p>
              </section>
            )}
          </>
        )}
        <WritingTools embedded />
      </div>
    );
  },
);
import { component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import { loadMetaFromIdb, saveMetaToIdb } from "../../utils/idb";
import {
  IN_FLOW_SETTING_EVENT,
  IN_FLOW_SETTING_KEY,
} from "../../utils/in-flow-events";
import {
  liveReviewSnapshot,
  type LiveReviewSnapshot,
} from "../../utils/live-review";

/** Always visible above the manuscript; feedback never requires opening the board. */
export const LiveReviewStatus = component$<{ folioId: string }>(
  ({ folioId }) => {
    const state = useStore({
      label: "Review follows your writing",
      detail: "",
      enabled: true,
      tools: true,
      expanded: false,
      unavailable: false,
    });
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(
      ({ track, cleanup }) => {
        track(() => folioId);
        let disposed = false;
        state.label = "Review follows your writing";
        state.detail = "";
        void loadMetaFromIdb<boolean>("live-review-enabled").then((value) => {
          if (!disposed) state.enabled = value !== false;
        });
        void loadMetaFromIdb<boolean>(IN_FLOW_SETTING_KEY).then((value) => {
          if (!disposed) state.tools = value !== false;
        });
        const quick = (event: Event) => {
          const detail = (
            event as CustomEvent<{
              folioId: string;
              label: string;
              detail: string;
            }>
          ).detail;
          if (detail.folioId !== folioId) return;
          state.label = detail.label;
          state.detail = detail.detail;
          if (!detail.detail) state.expanded = false;
        };
        const review = (event?: Event) => {
          const detail = event
            ? (event as CustomEvent<LiveReviewSnapshot>).detail
            : liveReviewSnapshot();
          if (detail.folioId !== folioId || state.detail) return;
          state.unavailable = detail.status === "unavailable";
          if (["paused", "offline", "unavailable"].includes(detail.status))
            state.label = detail.message;
        };
        review();
        window.addEventListener("twyne:quick-review", quick);
        window.addEventListener("twyne:live-review", review);
        cleanup(() => {
          disposed = true;
          window.removeEventListener("twyne:quick-review", quick);
          window.removeEventListener("twyne:live-review", review);
        });
      },
      { strategy: "document-ready" },
    );
    return (
      <div class="live-review-status">
        <div class="live-review-status__line">
          <span class="sr-only" role="status">
            {state.detail ? state.label : ""}
          </span>
          {state.detail ? (
            <button
              class="live-review-status__finding focus-ring"
              aria-expanded={state.expanded}
              onClick$={() => {
                state.expanded = !state.expanded;
              }}
            >
              <span aria-hidden="true">◇</span> {state.label}
            </button>
          ) : (
            <span class="live-review-status__label">{state.label}</span>
          )}
          <button
            class="live-review-status__toggle focus-ring"
            onClick$={async () => {
              state.enabled = !state.enabled;
              await saveMetaToIdb("live-review-enabled", state.enabled);
              state.detail = "";
              state.label = state.enabled
                ? "Review follows your writing"
                : "Automatic review paused";
              window.dispatchEvent(
                new CustomEvent("twyne:live-review-setting"),
              );
            }}
          >
            {state.enabled ? "Pause review" : "Resume review"}
          </button>
          {state.enabled && (
            <button
              class="live-review-status__toggle focus-ring"
              aria-pressed={state.tools}
              title="Small tools that appear in the margin when a passage is giving you trouble"
              onClick$={async () => {
                state.tools = !state.tools;
                await saveMetaToIdb(IN_FLOW_SETTING_KEY, state.tools);
                window.dispatchEvent(new CustomEvent(IN_FLOW_SETTING_EVENT));
              }}
            >
              {state.tools ? "Margin tools on" : "Margin tools off"}
            </button>
          )}
        </div>
        {state.expanded && state.detail && (
          <p class="live-review-status__detail">{state.detail}</p>
        )}
        {state.unavailable && (
          <Link href="/settings/" class="panel-meta focus-ring">
            Review account and AI settings ↗
          </Link>
        )}
      </div>
    );
  },
);

