    useVisibleTask$(async ({ track, cleanup }) => {
      const folioId = track(() => activeFolioId);
      let cancelled = false;
      cleanup(() => {
        cancelled = true;
      });
      const [cached, aiRaw, specs, history] = await Promise.all([
        loadRubricResultFromIdb(folioId),
