import { $, component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
import { WorkspacePreview } from "./workspace-preview";
import type { PanelId } from "../../utils/panel-activity";

export interface TourStop {
  id: string;
  /** Short label shown on the hotspot and the reader card. */
  tag: string;
  /** One or two sentences explaining this part of the room. */
  note: string;
  accent: string;
  /** Board tab the preview switches to while this stop is shown. */
  tab: PanelId;
  /** Folio the preview switches to while this stop is shown. */
  folioId: string;
  /** Rails this stop needs open to make sense. */
  drawer: boolean;
  panel: boolean;
  /**
   * Hotspot position in percent of the preview frame. Tuned for the full
   * three-column room; hotspots only render on wide screens where both
   * rails are docked, so these coordinates stay honest.
   */
  hotspot: { x: number; y: number };
  /**
   * Which side of the hotspot the reader slip hangs off. Pick the side
   * that leaves the described element visible.
   */
  placement: "above" | "below";
}

/**
 * The stops of the room tour. To explain a new part of the interface, add
 * an entry here — the hotspot, the reader card, the dots, and the preview
 * state all follow from this one list.
 */
export const TOUR_STOPS: TourStop[] = [
  {
    id: "dossier",
    tag: "The Dossier",
    note: "The brief every tool in the room reads — audience, purpose, and what good looks like — pinned beside the manuscript so no draft starts cold.",
    accent: "var(--color-cobalt)",
    tab: "personas",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 13, y: 30 },
    placement: "below",
  },
  {
    id: "folios",
    tag: "The Folios",
    note: "Draft, notes, outlines: every piece keeps its own folios in the drawer. Open one and watch the manuscript follow — this stop opens the research notes.",
    accent: "var(--color-vermilion)",
    tab: "personas",
    folioId: "folio-2",
    drawer: true,
    panel: true,
    hotspot: { x: 13, y: 62 },
    placement: "below",
  },
  {
    id: "manuscript",
    tag: "The Manuscript",
    note: "A serious long-form editor that stays out of the way while you write. Your words hold the centre; the room holds the edges.",
    accent: "var(--color-ink)",
    tab: "personas",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 50, y: 58 },
    placement: "below",
  },
  {
    id: "cast",
    tag: "The Cast",
    note: "Five editors read along and argue with the draft against your brief. Click one in the preview to hear its note on the passage.",
    accent: "var(--color-vermilion)",
    tab: "personas",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 86, y: 34 },
    placement: "above",
  },
  {
    id: "rubric",
    tag: "The Rubric",
    note: "Thesis, structure, style, evidence — each scored out of ten, and capped whenever a draft drifts off its subject.",
    accent: "var(--color-cobalt)",
    tab: "rubric",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 79, y: 11 },
    placement: "below",
  },
  {
    id: "marginalia",
    tag: "The Marginalia",
    note: "Every note lands where it belongs: anchored to the paragraph it argues with, never lost in a chat log.",
    accent: "var(--color-mustard)",
    tab: "comments",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 84, y: 11 },
    placement: "below",
  },
  {
    id: "apparatus",
    tag: "The Apparatus",
    note: "URLs, DOIs, ISBNs, and footnotes are detected as you cite them and kept where each can be inspected and verified.",
    accent: "var(--color-periwinkle)",
    tab: "citations",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 89, y: 11 },
    placement: "below",
  },
  {
    id: "versions",
    tag: "The Versions",
    note: "Every revision kept with its word count and its reason — the draft's memory, filed like everything else.",
    accent: "var(--color-sage)",
    tab: "history",
    folioId: "folio-1",
    drawer: true,
    panel: true,
    hotspot: { x: 94, y: 11 },
    placement: "below",
  },
];

import { describe, expect, test } from "bun:test";
import { BOARD_TABS } from "../editorial-board/board-tabs";
import { PERSONAS } from "../../utils/personas";
import { editorialDateline, folioNumeral } from "../../utils/editorial-format";
import { SPINE_CRITERIA } from "../../types";
import {
  PREVIEW_CRITERION_IDS,
  PREVIEW_FOLIO_IDS,
  PREVIEW_PERSONAS,
} from "./workspace-preview";
import { TOUR_STOPS } from "./workspace-tour";

/**
 * The landing preview is a mock of the live editor. Mocks drift: a renamed
 * persona, a new board tab, or a relabeled rubric criterion silently leaves
 * the landing page showing yesterday's room. The preview therefore renders
 * from the same sources as the editor (BOARD_TABS, PERSONAS,
 * SPINE_CRITERIA, the shared dateline and numerals), and these tests pin
 * every remaining hand-written id to its source so drift fails loudly.
 */
describe("board tabs", () => {
  test("are the five tabs the room actually has, in order", () => {
    expect(BOARD_TABS.map((t) => t.id)).toEqual([
      "personas",
      "rubric",
      "comments",
      "citations",
      "history",
    ]);
  });

  test("every tab carries its numeral, label, kicker, and accent", () => {
    for (const tab of BOARD_TABS) {
      expect(tab.numeral.trim()).not.toBe("");
      expect(tab.label.trim()).not.toBe("");
      expect(tab.kicker.trim()).not.toBe("");
      expect(tab.accent.trim()).not.toBe("");
    }
  });
});

describe("preview cast", () => {
  test("staffs exactly the resident editors, in order", () => {
    expect(PREVIEW_PERSONAS.map((p) => p.id)).toEqual(
      PERSONAS.map((p) => p.id),
    );
  });

  test("names, roles, colors, and marks come from the source personas", () => {
    for (const preview of PREVIEW_PERSONAS) {
      const real = PERSONAS.find((p) => p.id === preview.id)!;
      expect(preview.name).toBe(real.name);
      expect(preview.role).toBe(real.role);
      expect(preview.color).toBe(real.color);
      expect(preview.icon).toBe(real.icon);
    }
  });

  test("every editor has a margin note with an anchor", () => {
    for (const preview of PREVIEW_PERSONAS) {
      expect(preview.anchor.trim()).not.toBe("");
      expect(preview.note.trim()).not.toBe("");
    }
  });
});

describe("tour stops", () => {
  const tabIds = new Set(BOARD_TABS.map((t) => t.id));

  test("every stop names a real board tab and a real folio", () => {
    expect(TOUR_STOPS.length).toBeGreaterThan(0);
    for (const stop of TOUR_STOPS) {
      expect(tabIds.has(stop.tab)).toBe(true);
      expect(PREVIEW_FOLIO_IDS).toContain(stop.folioId);
    }
  });
});

describe("preview rubric", () => {
  test("grades only real spine criteria", () => {
    const spineIds = new Set(SPINE_CRITERIA.map((c) => c.id));
    expect(PREVIEW_CRITERION_IDS.length).toBeGreaterThan(0);
    for (const id of PREVIEW_CRITERION_IDS) {
      expect(spineIds.has(id)).toBe(true);
    }
  });
});

describe("shared editorial format", () => {
  test("dateline reads like the masthead", () => {
    expect(editorialDateline(new Date(2026, 3, 26))).toBe(
      "Vol. I · No. 116 · Sunday, the 26th of April, 2026",
    );
  });

  test("folio numerals run I–X, then plain numbers", () => {
    expect(folioNumeral(0)).toBe("I");
    expect(folioNumeral(2)).toBe("III");
    expect(folioNumeral(9)).toBe("X");
    expect(folioNumeral(10)).toBe("11");
  });
});

