import { IncomingMessage, ServerResponse } from 'node:http';

type PopmeltPluginOptions = {
    port?: number;
    projectRoot?: string;
    basePath?: string;
    bridge?: boolean;
};
type ConnectNext = () => void;
type ConnectMiddleware = (req: IncomingMessage, res: ServerResponse, next: ConnectNext) => void;
type DevServerLike = {
    config?: {
        server?: {
            host?: string | boolean;
            port?: number;
        };
    };
    middlewares: {
        use: (middleware: ConnectMiddleware) => void;
    };
    httpServer?: {
        once: (event: 'close', listener: () => void) => unknown;
    } | null;
};

export type { DevServerLike as D, PopmeltPluginOptions as P };
type PopmeltOptions = {
    enabled?: boolean;
    /** Experimental peer canvases, invitations and multiplayer UI. Default: false. */
    multiplayer?: boolean;
    bridgeUrl?: string;
    /** Stable project id generated by the framework plugin/bridge startup. */
    projectId?: string | null;
    /** Host router navigation, used for multi-page screenshot capture. */
    navigate?: (url: string) => void | Promise<unknown>;
    subjectAdapters?: readonly PopmeltSubjectAdapter[];
    extensions?: readonly PopmeltExtension[];
    /** Manual media annotation is enabled by default. */
    imageAnnotation?: boolean | Omit<ImageSubjectAdapterOptions, 'id'>;
    videoAnnotation?: boolean | Omit<VideoSubjectAdapterOptions, 'id'>;
    /** Capture application-owned JSON context with each submitted human turn. */
    getCommentMeta?: GetCommentMeta;
};

/** Public, credential-free description stamped by the application's dev server.
 * The revision is context metadata (or `unversioned`), never sync/Send authority.
 */
type ParticipantBootstrapConfig = {
    version?: 1;
    url: string;
    projectId: string;
    revision: string;
};
declare global {
    interface Window {
        __POPMELT_PARTICIPANTS__?: ParticipantBootstrapConfig;
    }
}
/** Available before mounting Popmelt so trusted apps can suppress startup effects.
 * This is a rendering hint, never a credential or an authorization decision.
 */
declare function isPopmeltPreview(url?: string): boolean;
