                        })),
                      ]}
                      onChange$={(value) => {
                        state.previousId = value;
                      }}
                    />
                  </label>
                  <label>
                    Later draft
                    <SiteSelect
                      ariaLabel="Later revision"
                      value={state.currentId}
                      options={[
                        { value: "current", label: "Current draft" },
