      if (result.status !== "unavailable" && !result.incomplete) {
        results.set(key, result);
        if (results.size > 48) results.delete(results.keys().next().value!);
      }
      return result;
    })
    .finally(() => pending.delete(key));
  pending.set(key, task);
  return task;
